import {attemptUsesLegacyExitos,captureQuestionRevisions,historicalQuestion,mergeBuiltinQuestions,resolveAttemptBank,isArchivedQuestion} from './engine/versioning';
import FiltersPanel from './components/PracticeFilters';
import ResultSummary from './components/ResultSummary';
import QuestionCard from './components/QuestionCard';
import PdfCollectionsPanel, {type PdfStartSettings} from './components/PdfCollectionsPanel';
import {collections, collectionOf, collectionName, collectionQuestions, collectionSources, ORIGINAL_COLLECTION} from './data/collections';
import {attemptCollection, canGrade, canPractice, makeCollectionAttempt} from './engine/collections';
import {useEffect,useMemo,useRef,useState,type ReactNode} from 'react';
import {BookOpen,LayoutDashboard,Route,PenLine,Timer,ChartNoAxesCombined,Library,Database,ArrowRight,ArrowLeft,ChevronRight,Check,CheckCheck,X,Flag,Search,Download,Upload,Play,Pause,Lightbulb,ExternalLink,Menu,Target,Layers,ShieldCheck,Bookmark,TriangleAlert,RotateCcw,GraduationCap,Clock,FileJson} from 'lucide-react';
import type {Question,Source,Progress,Attempt,Topic,Domain} from './types';
import {domains,tasks,topics} from './data/syllabus';import {initialQuestions,initialSources} from './data/bank';
import {DEFAULT_FILTERS,filterQuestions,type Filters} from './engine/practice';import {apportion,eligible,isCorrect,makeAttempt,maxComplete,pause,remaining,resume,score,selectQuestions,shuffle} from './engine/exam';
import {emptyProgress,loadProgress,recordResults,saveProgress,withAttempt} from './engine/persistence';import {parseBank,validateBank,validateProgress} from './engine/validation';
const nav=[['inicio','Mi centro',LayoutDashboard],['estudio','Ruta de estudio',Route],['practica','Practicar',PenLine],['simulacros','Simulacros',Timer],['resultados','Mis resultados',ChartNoAxesCombined],['biblioteca','Biblioteca',Library],['banco','Gestionar banco',Database]] as const;
const typeNames:Record<string,string>={conceptual:'Conceptual',situacional:'Situacional',calculo:'Cálculo',interpretacion:'Interpretación'},difficultyNames:Record<string,string>={basica:'Básica',intermedia:'Intermedia',avanzada:'Avanzada'},originNames:Record<string,string>={ia:'Original de IA',externa:'Importada del documento',adaptada:'Adaptada'};
const safeReadBank=()=>{try{const raw=localStorage.getItem('leython-capm-bank-v1');if(raw){const bank=parseBank(raw);return {questions:mergeBuiltinQuestions(bank.questions,collectionQuestions),sources:[...bank.sources,...collectionSources.filter(s=>!bank.sources.some(old=>old.id===s.id))],error:null}}}catch(e){return {questions:[...initialQuestions,...collectionQuestions],sources:[...initialSources,...collectionSources],error:'El banco guardado no pudo recuperarse. Se cargó el banco inicial sin sobrescribir el respaldo. '+String(e)}}return {questions:[...initialQuestions,...collectionQuestions],sources:[...initialSources,...collectionSources],error:null}};
function download(name:string,data:unknown){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function Badge({children,tone='neutral'}:{children:ReactNode;tone?:string}){return <span className={'badge '+tone}>{children}</span>}
function ProgressBar({value,color='#4f17a8'}:{value:number;color?:string}){return <div className="progress-track" role="progressbar" aria-valuenow={Math.round(value)} aria-valuemin={0} aria-valuemax={100}><i style={{width:Math.max(0,Math.min(100,value))+'%',background:color}}/></div>}
function Empty({title,text,action}:{title:string;text:string;action?:ReactNode}){return <div className="empty"><BookOpen size={32}/><h3>{title}</h3><p>{text}</p>{action}</div>}
function RefList({ids,sources:catalog}:{ids:string[];sources:Source[]}){return <div className="refs">{ids.map(id=>{const s=catalog.find(x=>x.id===id);return s?<a key={id} href={s.localUrl??s.url} target="_blank" rel="noreferrer"><ExternalLink size={14}/><span>{s.title}<small>{s.author} · {s.section} · Consulta: {s.accessed}{s.status==='no-accesible'?' · Acceso pendiente':''}</small></span></a>:<p key={id}>Referencia no disponible: {id}</p>})}</div>}
export default function App(){
const [bankState]=useState(safeReadBank);const [bank,setBank]=useState<Question[]>(bankState.questions);const [catalog,setCatalog]=useState<Source[]>(bankState.sources);const [loaded]=useState(()=>loadProgress(bankState.questions));const [p,setP]=useState<Progress>(loaded.progress);const [storageBlocked,setStorageBlocked]=useState(!!loaded.error||!!bankState.error);const [notice,setNotice]=useState(loaded.error??bankState.error??'');const [page,setPage]=useState(()=>location.hash.slice(1).split('/')[0]||'inicio');const [menu,setMenu]=useState(false);const [selectedDomain,setSelectedDomain]=useState(1);const [selectedTopic,setSelectedTopic]=useState<Topic|null>(()=>topics.find(t=>t.id===decodeURIComponent(location.hash.slice(1).split('/')[1]??''))??null);const [filters,setFilters]=useState<Filters>({...DEFAULT_FILTERS});const [now,setNow]=useState(Date.now());const [resultId,setResultId]=useState<string|null>(null);const [reviewId,setReviewId]=useState<string|null>(null);const [reviewFilter,setReviewFilter]=useState('');const [resultCollection,setResultCollection]=useState('all');const [practiceShuffle,setPracticeShuffle]=useState(false);const [libTab,setLibTab]=useState('todas');const [libSearch,setLibSearch]=useState('');const [simCount,setSimCount]=useState(20);const [simMinutes,setSimMinutes]=useState(30);const [simDomains,setSimDomains]=useState([1,2,3,4]);const [simDifficulty,setSimDifficulty]=useState('');const [confirmFinish,setConfirmFinish]=useState(false);const [importError,setImportError]=useState('');const [importStatus,setImportStatus]=useState('');const mainRef=useRef<HTMLElement>(null);
const originalBank=bank.filter(q=>collectionOf(q)===ORIGINAL_COLLECTION);const active=p.attempts.find(a=>a.id===p.activeId&&!a.finishedAt)??null;const session=active&&(page==='practica'||page==='simulacros')?active:null;const answeredIds=new Set(p.history.map(h=>h.questionId));const gradedHistoryCount=p.history.filter(h=>{const current=bank.find(q=>q.id===h.questionId);const q=current?historicalQuestion(current,h.attemptId,p.attempts):undefined;return !!q&&canGrade(q)}).length;const correctHistory=p.history.filter(h=>{const current=bank.find(q=>q.id===h.questionId);const q=current?historicalQuestion(current,h.attemptId,p.attempts):undefined;return q&&canGrade(q)&&isCorrect(q,{selectedIds:h.selectedIds,confirmed:true})}).length;const filtered=useMemo(()=>filterQuestions(bank,filters,p),[bank,filters,p]);const completed=p.attempts.filter(a=>a.finishedAt&&(resultCollection==='all'||attemptCollection(a,bank)===resultCollection)).sort((a,b)=>(b.finishedAt??0)-(a.finishedAt??0));const viewedResult=completed.find(a=>a.id===resultId)??completed[0];const sessionBank=session?resolveAttemptBank(session,bank):bank;const resultBank=viewedResult?resolveAttemptBank(viewedResult,bank):bank;
useEffect(()=>{const onHash=()=>{const [route,id]=location.hash.slice(1).split('/');setPage(nav.some(n=>n[0]===route)?route:'inicio');if(id)setSelectedTopic(topics.find(t=>t.id===decodeURIComponent(id))??null);setMenu(false)};addEventListener('hashchange',onHash);return ()=>removeEventListener('hashchange',onHash)},[]);
useEffect(()=>{if(storageBlocked)return;try{saveProgress(p)}catch{setStorageBlocked(true);setNotice('No se pudo guardar el progreso. Exporta un respaldo desde Gestionar banco.')}},[p,storageBlocked]);
useEffect(()=>{const id=setInterval(()=>setNow(Date.now()),1000);return ()=>clearInterval(id)},[]);
useEffect(()=>{if(active&&active.mode!=='practica'&&!active.pausedAt&&remaining(active,now)<=0)finishAttempt(active,true)},[now,active?.id]);
useEffect(()=>{if(page==='estudio'&&selectedTopic)setP(x=>x.visited.includes(selectedTopic.id)?x:{...x,visited:[...x.visited,selectedTopic.id]})},[page,selectedTopic?.id]);
useEffect(()=>{const handler=(e:KeyboardEvent)=>{const target=e.target as HTMLElement;if(e.key==='Escape')setMenu(false);if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(target.tagName)&&!target.isContentEditable){e.preventDefault();go('biblioteca');setTimeout(()=>document.getElementById('library-search')?.focus(),100)}};addEventListener('keydown',handler);return()=>removeEventListener('keydown',handler)},[]);
function go(next:string){setPage(next);location.hash=next;setMenu(false);setReviewId(null);setConfirmFinish(false);setP(x=>({...x,lastPage:next}));mainRef.current?.focus();window.scrollTo({top:0,behavior:'instant'})}
function openTopic(t:Topic){setSelectedTopic(t);setSelectedDomain(Number(t.taskId[1]));go('estudio');location.hash='estudio/'+t.id;setP(x=>({...x,visited:[...new Set([...x.visited,t.id])]}))}
function changeFilters(k:keyof Filters,value:string){setFilters(f=>({...f,[k]:value,...(k==='collection'?{domain:'',task:'',topic:'',review:value===ORIGINAL_COLLECTION?'contrastado':''}:k==='domain'?{task:'',topic:''}:k==='task'?{topic:''}:{})}))}
function startPractice(list:Question[]){if(active){setNotice('Tienes una sesión guardada. Continúala o finalízala antes de iniciar otra.');go(active.mode==='practica'?'practica':'simulacros');return}if(!list.length){setNotice('No hay preguntas para esos filtros.');return}list=list.filter(canPractice);const collectionIds=[...new Set(list.map(collectionOf))];if(!list.length)return;if(collectionIds.length>1&&filters.collection!=='all'){setNotice('Selecciona expresamente combinar colecciones antes de mezclarlas.');return}if(list.some(q=>!canGrade(q))&&!window.confirm('Esta práctica incluye preguntas sin clave o ambiguas. Se mostrarán sin calificación y no contarán como errores. ¿Continuar?'))return;const ordered=[...list].sort((a,b)=>(a.originalNumber??0)-(b.originalNumber??0));const ids=(practiceShuffle?shuffle(ordered,Date.now()):ordered).map(q=>q.id);const a={...makeAttempt(ids,'practica',p.seen,0),collectionId:collectionIds.length===1?collectionIds[0]:'mixed',collectionIds,questionRevisions:captureQuestionRevisions(list),shuffleOptions:collectionIds.some(id=>id!==ORIGINAL_COLLECTION)?false:p.preferences.shuffle,questionOrder:practiceShuffle?'shuffled' as const:'original' as const};setP(x=>withAttempt(x,a));go('practica')}
function startSim(full:boolean,short=false){if(active){setNotice('Continúa o finaliza tu sesión guardada antes de iniciar otra.');go(active.mode==='practica'?'practica':'simulacros');return}try{const pool=originalBank.filter(q=>!simDifficulty||q.difficulty===simDifficulty);const count=full?150:short?Math.min(simCount,eligible(pool).filter(q=>simDomains.includes(q.domain)).length):simCount;const ids=selectQuestions(full?originalBank:pool,count,p.seen,full?[1,2,3,4]:simDomains,full,Date.now());const a=makeAttempt(ids,full?'completo':'personalizado',p.seen,full?180:simMinutes);setP(x=>withAttempt(x,a));go('simulacros')}catch(e){setNotice(String((e as Error).message))}}
function startPdf(id:string,settings:PdfStartSettings){if(active){setNotice('Continúa o finaliza la sesión activa antes de empezar otro intento.');go(active.mode==='practica'?'practica':'simulacros');return}try{const a=makeCollectionAttempt(bank,id,p.seen,settings);setP(x=>withAttempt(x,a));go(a.mode==='practica'?'practica':'simulacros')}catch(e){setNotice((e as Error).message)}}
function answer(ids:string[],confirm=false){if(!session||session.pausedAt||session.finishedAt)return;if(session.mode!=='practica'&&remaining(session)<=0){finishAttempt(session,true);return}const q=sessionBank.find(q=>q.id===session.questionIds[session.index])!;if(session.mode==='practica'&&session.answers[q.id]?.confirmed)return;const a={...session,answers:{...session.answers,[q.id]:{selectedIds:ids,confirmed:confirm,at:Date.now()}}};setP(x=>{let out=withAttempt({...x,seen:[...new Set([...x.seen,q.id])]},a);if(confirm)out={...out,history:[...out.history.filter(h=>!(h.attemptId===a.id&&h.questionId===q.id)),{questionId:q.id,selectedIds:ids,at:Date.now(),attemptId:a.id,wasNew:a.newIds.includes(q.id)}]};return out})}
function navigateQuestion(index:number){if(!session||index<0||index>=session.questionIds.length)return;setP(x=>withAttempt(x,{...session,index}));setConfirmFinish(false)}
function finishAttempt(a:Attempt,expired=false){const ended={...a,pausedAt:null,finishedAt:expired&&a.deadline?a.deadline:Date.now()};setP(x=>recordResults(withAttempt(x,ended),ended));setResultId(a.id);setResultCollection(attemptCollection(a,bank));setConfirmFinish(false);go('resultados');if(expired)setNotice('Se agotó el tiempo. El intento y tus respuestas quedaron guardados.')}
function bookmark(id:string){setP(x=>({...x,bookmarks:x.bookmarks.includes(id)?x.bookmarks.filter(v=>v!==id):[...x.bookmarks,id]}))}
function note(id:string,text:string){setP(x=>({...x,notes:{...x.notes,[id]:text}}))}
function report(id:string,text:string){setP(x=>({...x,reports:[...x.reports,{questionId:id,text,at:Date.now()}]}));setNotice('Reporte guardado en tu progreso.')}
function questionStats(qs:Question[]){const ids=new Set(qs.map(q=>q.id));const h=p.history.filter(h=>ids.has(h.questionId));const gh=h.filter(h=>canGrade(qs.find(q=>q.id===h.questionId)!));const right=gh.filter(h=>{const q=bank.find(q=>q.id===h.questionId)!;return isCorrect(q,{selectedIds:h.selectedIds,confirmed:true})}).length;return {answered:new Set(h.map(h=>h.questionId)).size,total:qs.length,attempts:gh.length,performance:gh.length?Math.round(right/gh.length*100):null}}
async function importFile(file:File|undefined,kind:'bank'|'progress'){if(!file)return;setImportError('');setImportStatus('Validando archivo…');try{if(file.size>15*1024*1024)throw Error('El archivo supera el límite de 15 MB.');const text=await file.text();if(kind==='bank'){if(active)throw Error('Finaliza la sesión activa antes de cambiar el banco.');const b=parseBank(text);const mergedSources=[...catalog];for(const s of b.sources){const old=mergedSources.find(x=>x.id===s.id);if(old&&JSON.stringify(old)!==JSON.stringify(s))throw Error('La fuente '+s.id+' ya existe con otro contenido. Usa un ID nuevo.');if(!old)mergedSources.push(s)}const merged=[...bank];for(const q of b.questions){const old=merged.find(x=>x.id===q.id);if(old&&isArchivedQuestion(q)&&(old.revision??1)>(q.revision??1))continue;if(old&&JSON.stringify(old)!==JSON.stringify(q))throw Error('La pregunta '+q.id+' ya existe con otro contenido. No se sobrescribió.');if(!old)merged.push(q)}const errors=validateBank({formatVersion:1,questions:merged,sources:mergedSources});if(errors.length)throw Error(errors.slice(0,10).join('\n'));localStorage.setItem('leython-capm-bank-v1',JSON.stringify({formatVersion:1,questions:merged,sources:mergedSources}));setBank(merged);setCatalog(mergedSources);setImportStatus('Importación válida: '+(merged.length-bank.length)+' preguntas nuevas. El progreso se conservó.')}else{let data;try{data=JSON.parse(text)}catch{throw Error('El archivo no contiene JSON válido.')}const errors=validateProgress(data,bank);if(errors.length)throw Error(errors.slice(0,10).join('\n'));localStorage.setItem('leython-capm-progress-backup-v1',JSON.stringify(p));saveProgress(data);setStorageBlocked(false);setP(data);setImportStatus('Progreso importado. Se guardó una copia local del progreso anterior.')}}catch(e){setImportStatus('');setImportError((e as Error).message)}}
function domainCard(d:Domain){const qs=originalBank.filter(q=>q.domain===d.id),s=questionStats(qs),ts=topics.filter(t=>Number(t.taskId[1])===d.id);return <button className="domain-card" style={{'--domain-color':d.color} as React.CSSProperties} key={d.id} onClick={()=>{setSelectedDomain(d.id);setSelectedTopic(null);go('estudio')}}><div className="domain-card-top"><span className="domain-number">0{d.id}</span><span className="domain-weight">{d.weight}% del examen</span><ArrowRight size={19}/></div><h3>{d.short}</h3><p>{d.description}</p><div className="domain-meta"><span>{tasks.filter(t=>t.domain===d.id).length} tareas · {qs.length} preguntas</span><b>{s.answered}/{s.total}</b></div><ProgressBar value={s.answered/s.total*100} color={d.color}/><div className="domain-foot"><span>{p.visited.filter(id=>ts.some(t=>t.id===id)).length}/{ts.length} temas visitados</span><span>{s.performance===null?'Sin rendimiento aún':s.performance+'% de aciertos'}</span></div></button>}
const currentTitle=nav.find(n=>n[0]===page)?.[1]??'Mi centro';const sessionQ=session?sessionBank.find(q=>q.id===session.questionIds[session.index]):null;const taskOfTopic=selectedTopic?tasks.find(t=>t.id===selectedTopic.taskId):null;const simAvailable=eligible(bank).filter(q=>simDomains.includes(q.domain)&&(!simDifficulty||q.difficulty===simDifficulty));const completeCounts=apportion(150);const apt=eligible(bank).length;const fullPreview=maxComplete(bank)>=150?selectQuestions(bank,150,p.seen,[1,2,3,4],true,1):[];
return <div className="app-shell"><a href="#main" className="skip-link" onClick={e=>{e.preventDefault();mainRef.current?.focus()}}>Ir al contenido</a><aside className={'sidebar '+(menu?'open':'')}><a href="#inicio" className="brand" onClick={()=>go('inicio')}><span className="brand-symbol"><BookOpen size={24}/></span><span>CAPM<span className="brand-sub">CENTRO DE ESTUDIO</span></span></a><div className="workspace-label">TU ESPACIO DE APRENDIZAJE</div><nav aria-label="Navegación principal">{nav.map(([id,title,Icon])=><button key={id} className={page===id?'nav-item active':'nav-item'} onClick={()=>go(id)}><Icon size={19}/>{title}{id==='practica'&&<small>{bank.length}</small>}</button>)}</nav><div className="sidebar-bottom"><div className="local-status"><span/> Progreso en este navegador</div><div className="profile"><span className="avatar">L</span><div><b>Leython</b><small>Mi preparación CAPM</small></div><GraduationCap size={18}/></div></div></aside>{menu&&<button className="menu-overlay" aria-label="Cerrar menú" onClick={()=>setMenu(false)}/>}<div className="main-shell"><header className="topbar"><button className="icon-button mobile-menu" aria-label="Abrir menú" onClick={()=>setMenu(!menu)}><Menu/></button><div className="top-breadcrumb">Mi aprendizaje <ChevronRight size={14}/><b>{currentTitle}</b></div><div className="top-actions"><span className="date">{new Date().toLocaleDateString('es-PE',{day:'numeric',month:'long'})}</span><button className="header-search" onClick={()=>{go('biblioteca');setTimeout(()=>document.getElementById('library-search')?.focus(),50)}}><Search size={16}/> Buscar un concepto <kbd>/</kbd></button><span className="avatar small-avatar">L</span></div></header><main id="main" ref={mainRef} tabIndex={-1}>
{notice&&<div className="notice" role="status"><TriangleAlert size={18}/><span>{notice}</span><button className="icon-button" aria-label="Cerrar aviso" onClick={()=>setNotice('')}><X size={16}/></button></div>}
{storageBlocked&&<div className="notice error"><span>Guardado suspendido para proteger el respaldo existente. Exporta los datos antes de habilitar el guardado.</span><button className="button secondary small" onClick={()=>download('capm-progreso-rescate.json',p)}>Exportar datos actuales</button><button className="button secondary small" onClick={()=>{try{const old=localStorage.getItem('leython-capm-v1');if(old)localStorage.setItem('leython-capm-damaged-backup',old);saveProgress(p);setStorageBlocked(false);setNotice('Guardado habilitado. El contenido anterior quedó respaldado.')}catch{setNotice('El navegador no permite escribir el respaldo.')}}}>Respaldar y habilitar</button></div>}
{page==='inicio'&&<><div className="eyebrow">UN PASO MÁS CERCA DE TU OBJETIVO</div><section className="welcome"><div><h1>Tu centro de estudio, <em>Leython.</em></h1><p>Elige una colección, estudia un tema o retoma tu última sesión.</p><div className="button-row"><button className="button primary" onClick={()=>{setSelectedTopic(null);go('estudio')}}>Continuar mi ruta <ArrowRight size={18}/></button><button className="button text" onClick={()=>go('practica')}>Ir a practicar <ChevronRight size={17}/></button></div><div className="hero-caption"><span className="tiny-dot"/> A tu ritmo · En español · Sin distracciones</div></div><div className="hero-art" aria-hidden="true"><div className="orbit o1"/><div className="orbit o2"/><div className="hero-card hc-top"><ShieldCheck size={17}/><span>Aprender con fundamento</span></div><div className="hero-center"><BookOpen size={45}/><span>CAPM</span><small>UN NUEVO HORIZONTE</small></div><div className="hero-card hc-bottom"><Target size={18}/><span>Tu camino, paso a paso</span></div><div className="orbit-dot od1"/><div className="orbit-dot od2"/></div></section>
<div className="stats-grid"><div className="stat"><span className="stat-icon teal"><BookOpen size={20}/></span><div><strong>{p.visited.length}<small> / {topics.length}</small></strong><p>Temas visitados</p></div></div><div className="stat"><span className="stat-icon blue"><CheckCheck size={20}/></span><div><strong>{answeredIds.size}<small> / {bank.length}</small></strong><p>Preguntas respondidas</p></div></div><div className="stat"><span className="stat-icon sand"><Target size={20}/></span><div><strong>{gradedHistoryCount?Math.round(correctHistory/gradedHistoryCount*100)+'%':'—'}</strong><p>Rendimiento · {gradedHistoryCount} respuestas calificables</p></div></div><div className="stat"><span className="stat-icon purple"><Layers size={20}/></span><div><strong>{originalBank.length}<small> / 300</small></strong><p>Preguntas del objetivo inicial</p></div></div></div>
{active&&<section className="resume-strip"><div className="stat-icon teal"><Play size={20}/></div><div><b>Tienes una sesión por continuar</b><p>{active.mode==='practica'?'Práctica':active.mode==='completo'?'Simulacro completo':'Simulacro personalizado'} · Pregunta {active.index+1} de {active.questionIds.length} · {Object.values(active.answers).filter(a=>a.selectedIds.length).length} respondidas</p></div><button className="button primary small" onClick={()=>go(active.mode==='practica'?'practica':'simulacros')}>Retomar sesión <ArrowRight size={16}/></button></section>}
{!active&&completed[0]&&<section className="resume-strip"><div className="stat-icon blue"><ChartNoAxesCombined size={20}/></div><div><b>Tu última sesión</b><p>{new Date(completed[0].startedAt).toLocaleString('es-PE')} · {completed[0].questionIds.length} preguntas · {score(completed[0],bank).graded?score(completed[0],bank).percent+'% de aciertos':'Sin calificación'}</p></div><button className="button secondary small" onClick={()=>{setResultId(completed[0].id);go('resultados')}}>Revisar resultados <ArrowRight size={16}/></button></section>}
<div className="section-heading"><div><span className="eyebrow">EL MAPA DE TU PREPARACIÓN</span><h2>Cuatro dominios. Un objetivo.</h2></div><button className="link-button" onClick={()=>go('estudio')}>Ver toda mi ruta <ArrowRight size={16}/></button></div><div className="domains-grid">{domains.map(domainCard)}</div>
<div className="bottom-grid"><section className="panel next-step"><div className="panel-heading"><Lightbulb size={20}/><h3>Tu siguiente paso</h3></div><p>{p.history.length?'Revisa tus errores y distingue el concepto que hizo cambiar tu respuesta.':'Empieza por un tema, lee su ejemplo y resuelve preguntas antes de mirar la explicación.'}</p><button className="link-button" onClick={()=>{if(p.history.length){setFilters({...DEFAULT_FILTERS,status:'incorrectas'});go('practica')}else openTopic(topics[0])}}>{p.history.length?'Repasar preguntas incorrectas':'Explorar procesos y ciclos de vida'} <ArrowRight size={16}/></button></section><section className="panel source-note"><div className="panel-heading"><ShieldCheck size={20}/><h3>Estudia con transparencia</h3></div><p>{apt} preguntas con fundamento contrastado y {bank.length-apt} pendientes. Originales de IA, con revisión humana indicada por separado.</p><button className="link-button" onClick={()=>go('banco')}>Consultar cobertura y pendientes <ArrowRight size={16}/></button></section></div><p className="fine-print">Visitar contenido, responder y rendir bien son indicadores diferentes. Ninguno, por sí solo, acredita dominio del tema o garantiza aprobar el CAPM.</p></>}
{page==='estudio'&&<><PageTitle eyebrow="APRENDER PARA COMPRENDER" title="Tu ruta de estudio" text="Dominio del examen → tarea → subtema. Lee, conecta ideas y practica."/>{selectedTopic?<><div className="study-breadcrumb"><button onClick={()=>{setSelectedTopic(null);location.hash='estudio'}}>Dominios</button><ChevronRight size={13}/><span>D{taskOfTopic?.domain}</span><ChevronRight size={13}/><span>{selectedTopic.taskId}</span><ChevronRight size={13}/><b>{selectedTopic.title}</b></div><article className="study-article"><div className="chip-row"><Badge tone="teal">{selectedTopic.taskId}</Badge><Badge>{taskOfTopic?.title}</Badge><Badge>✓ Contenido visitado</Badge></div><h2>{selectedTopic.title}</h2><p className="lead">{selectedTopic.summary}</p><div className="lesson-example"><span className="eyebrow">LLEVADO A LA PRÁCTICA</span><p>{selectedTopic.example}</p></div><div className="concept-box"><Lightbulb size={21}/><div><b>No confundas los conceptos</b><p>{selectedTopic.contrast}</p></div></div><div className="terms">{selectedTopic.terms.map(t=><span key={t}>{t}</span>)}</div><h3>Comprueba el fundamento</h3><RefList ids={selectedTopic.refs} sources={catalog}/>{bank.some(q=>q.topicId===selectedTopic.id&&q.review==='pendiente')&&<p className="notice">Este módulo tiene ejercicios pendientes de contraste. La explicación es introductoria; revisa las fuentes antes de usarla como referencia definitiva.</p>}<div className="lesson-footer"><button className="button primary" onClick={()=>{setFilters({...DEFAULT_FILTERS,domain:String(taskOfTopic?.domain),task:selectedTopic.taskId,topic:selectedTopic.id,review:''});startPractice(originalBank.filter(q=>q.topicId===selectedTopic.id))}}>Practicar este tema <ArrowRight size={17}/></button><span>{questionStats(originalBank.filter(q=>q.topicId===selectedTopic.id)).answered} preguntas distintas respondidas</span></div></article></>:<><div className="domain-tabs" role="group" aria-label="Elegir dominio">{domains.map(d=><button key={d.id} className={selectedDomain===d.id?'selected':''} onClick={()=>setSelectedDomain(d.id)}><i style={{background:d.color}}/>D{d.id} · {d.short}<small>{d.weight}%</small></button>)}</div><section className="module-intro"><span className="domain-number" style={{color:domains[selectedDomain-1]?.color}}>0{selectedDomain}</span><div><h2>{domains[selectedDomain-1]?.title}</h2><p>{tasks.filter(t=>t.domain===selectedDomain).length} tareas · {topics.filter(t=>Number(t.taskId[1])===selectedDomain).length} subtemas · Identificadores del temario conservados</p></div></section><div className="task-list">{tasks.filter(t=>t.domain===selectedDomain).map(t=>{const ts=topics.filter(x=>x.taskId===t.id);const st=questionStats(bank.filter(q=>q.taskId===t.id));return <details className="task-group" key={t.id} open><summary><span className="task-id">{t.id}</span><h3>{t.title}</h3><span>{st.answered}/{st.total} respondidas</span><ChevronRight size={17}/></summary><div>{ts.map(topic=>{const stats=questionStats(bank.filter(q=>q.topicId===topic.id));return <button className="topic-row" key={topic.id} onClick={()=>openTopic(topic)}><span className={'topic-status '+(p.visited.includes(topic.id)?'visited':'')}>{p.visited.includes(topic.id)?<Check size={14}/>:<BookOpen size={14}/>}</span><div><b>{topic.title}</b><small>{p.visited.includes(topic.id)?'Visitado':'Por visitar'} · {stats.answered}/{stats.total} respondidas · {stats.performance===null?'Sin rendimiento':stats.performance+'% en '+stats.attempts+' respuestas'}</small></div>{bank.some(q=>q.topicId===topic.id&&q.review==='pendiente')&&<Badge tone="amber">Contraste pendiente</Badge>}<ChevronRight size={16}/></button>})}</div></details>})}</div></> }</>}
{(page==='practica'||page==='simulacros')&&session&&sessionQ?<>{attemptUsesLegacyExitos(session)&&<div className="notice">Esta sesión conserva las preguntas y la calificación originales. Para utilizar las 55 respuestas revisadas, finaliza esta sesión e inicia un intento nuevo. Tu historial y tus notas se conservan.</div>}<div className="session-header"><div><span className="eyebrow">{session.mode==='practica'?'PRÁCTICA CON RETROALIMENTACIÓN':session.mode==='completo'?'SIMULACRO COMPLETO DE PRÁCTICA':session.mode==='pdf'?'SIMULADOR PDF · '+collectionName(session.collectionId):'SIMULACRO PERSONALIZADO'}</span><h1>Pregunta {session.index+1}<small> de {session.questionIds.length}</small></h1></div>{session.mode!=='practica'&&<div className={'timer '+(remaining(session,now)<300000?'urgent':'')}><Clock size={19}/>{formatTime(remaining(session,now))}{session.mode==='personalizado'&&<button className="icon-button" aria-label={session.pausedAt?'Reanudar cronómetro':'Pausar cronómetro'} onClick={()=>setP(x=>withAttempt(x,session.pausedAt?resume(session):pause(session)))}>{session.pausedAt?<Play size={18}/>:<Pause size={18}/>}</button>}</div>}</div><ProgressBar value={(Object.values(session.answers).filter(a=>a.selectedIds.length).length/session.questionIds.length)*100}/><div className="session-layout"><div><div className="session-context"><span className="badge">{collectionName(attemptCollection(session,bank))}</span><span>D{sessionQ.domain} · {sessionQ.taskId} · {topics.find(t=>t.id===sessionQ.topicId)?.title}</span><Badge>{session.newIds.includes(sessionQ.id)?'Nueva al iniciar':'Ya estudiada'}</Badge></div>{session.pausedAt?<div className="pause-screen"><Pause size={35}/><h2>Una pausa para volver con claridad</h2><p>El cronómetro del modo personalizado está detenido. Reanuda para ver y responder las preguntas.</p><button className="button primary" onClick={()=>setP(x=>withAttempt(x,resume(session)))}>Reanudar sesión <Play size={17}/></button></div>:<QuestionCard q={sessionQ} attempt={session} progress={p} sources={catalog} solution={session.mode==='practica'&&!!session.answers[sessionQ.id]?.confirmed} shuffleOptions={session?.shuffleOptions??p.preferences.shuffle} onAnswer={answer} onBookmark={()=>bookmark(sessionQ.id)} onNote={text=>note(sessionQ.id,text)} onReport={text=>report(sessionQ.id,text)}/>}<div className="session-controls"><button className="button secondary" disabled={session.index===0} onClick={()=>navigateQuestion(session.index-1)}><ArrowLeft size={16}/> Anterior</button><button className="button secondary" onClick={()=>setP(x=>withAttempt(x,{...session,flagged:session.flagged.includes(sessionQ.id)?session.flagged.filter(id=>id!==sessionQ.id):[...session.flagged,sessionQ.id]}))}><Flag size={16}/>{session.flagged.includes(sessionQ.id)?'Quitar duda':'Marcar duda'}</button><button className="button primary" disabled={session.index===session.questionIds.length-1} onClick={()=>navigateQuestion(session.index+1)}>Siguiente <ArrowRight size={16}/></button></div></div><aside className="question-map"><h3>Tu sesión</h3><p>{Object.values(session.answers).filter(a=>a.selectedIds.length).length} respondidas · {session.flagged.length} dudas</p><div className="question-grid">{session.questionIds.map((id,i)=><button key={id} className={(i===session.index?'current ':'')+(session.answers[id]?.selectedIds.length?'answered ':'')+(session.flagged.includes(id)?'flagged':'')} aria-label={'Ir a pregunta '+(i+1)+(session.flagged.includes(id)?', marcada como duda':'')} onClick={()=>navigateQuestion(i)}>{i+1}{session.flagged.includes(id)&&<span>⚑</span>}</button>)}</div><div className="map-legend"><span>● Respondida</span><span>⚑ Duda</span><span>□ Sin responder</span></div><p className="fine-print">Guardado automático en este navegador. {session.mode==='completo'?'El tiempo continúa al salir o recargar.':'Puedes retomar esta sesión después.'}</p>{confirmFinish?<div className="finish-confirm"><b>¿Finalizar y ver resultados?</b><p>{session.questionIds.length-Object.values(session.answers).filter(a=>a.selectedIds.length).length} preguntas sin responder.</p><button className="button primary small" onClick={()=>finishAttempt(session)}>Finalizar ahora</button><button className="button text small" onClick={()=>setConfirmFinish(false)}>Seguir respondiendo</button></div>:<button className="button secondary full-width" onClick={()=>setConfirmFinish(true)}>Finalizar sesión <Check size={16}/></button>}</aside></div></>:
page==='practica'?<><PageTitle eyebrow="PON A PRUEBA LO QUE SABES" title="Practica con intención" text="Elige tus filtros. Responde y confirma antes de consultar las explicaciones."/><div className="practice-layout"><section className="panel filter-panel"><h3><Layers size={18}/> Tu selección</h3><FiltersPanel filters={filters} onChange={changeFilters}/><button className="link-button" onClick={()=>setFilters({...DEFAULT_FILTERS})}><RotateCcw size={14}/> Restablecer filtros</button></section><section><div className="practice-feature"><div className="eyebrow">CADA RESPUESTA ES UNA OPORTUNIDAD</div><h2>Responde y comprende</h2><p className="active-collection"><b>Colección:</b> {filters.collection==='all'?'Combinación elegida expresamente':collectionName(filters.collection)}</p><p>Revisa la explicación de todas las alternativas, descubre las confusiones habituales y guarda tus notas.</p><div className="practice-number">{filtered.length}<span>preguntas para tu selección</span></div><div className="chip-row"><Badge tone="teal">{filtered.filter(q=>!p.seen.includes(q.id)).length} nuevas</Badge><Badge>{filtered.filter(q=>q.choose>1).length} de selección múltiple</Badge></div><label className="practice-shuffle"><input type="checkbox" checked={practiceShuffle} onChange={e=>setPracticeShuffle(e.target.checked)}/> Barajar preguntas</label>{filtered.some(q=>!canGrade(q))&&<p className="notice">{filtered.filter(q=>!canGrade(q)).length} preguntas sin clave utilizable: se mostrarán sin calificación y no contarán como errores.</p>}<button className="button primary" disabled={!filtered.length} onClick={()=>startPractice(filtered)}>Comenzar práctica <ArrowRight size={18}/></button></div>{!filtered.length&&<Empty title="No hay preguntas con estos filtros" text="Prueba otro subtema o cambia el estado de revisión."/>}<p className="fine-print">“Nuevas” significa sin selección registrada en este navegador. Las preguntas pendientes solo aparecen si cambias el filtro de revisión. La dificultad es estimada.</p></section></div></>:
page==='simulacros'?<><PageTitle eyebrow="ENTRENA TU RITMO Y TUS DECISIONES" title="Elige tu simulacro" text="Sin soluciones durante el intento. Con análisis completo al terminar."/><section aria-labelledby="custom-simulators-heading"><div className="section-heading"><div><h2 id="custom-simulators-heading">Simulacros personalizados</h2><p>Banco original · CAPM. Las preguntas de tus PDF se mantienen aparte.</p></div></div><div className="sim-grid"><section className="panel complete-sim"><Badge tone="teal">LOS CUATRO DOMINIOS</Badge><Timer size={40} className="sim-icon"/><h2>Completo de práctica</h2><p>Una sesión extensa para integrar lo aprendido.</p><div className="sim-big-stats"><div><b>150</b><span>preguntas únicas</span></div><div><b>180</b><span>minutos continuos</span></div></div><div className="weight-strip">{domains.map((d,i)=><span key={d.id} style={{background:d.color,flex:d.weight}}>D{d.id} · {completeCounts[i]}</span>)}</div><ul className="rules"><li>Prioriza preguntas no vistas. No repite dentro del intento.</li><li>Solo preguntas con fundamento contrastado.</li><li>Fecha límite persistida: recargar no reinicia el tiempo.</li><li>Sin pausa. Las soluciones aparecen al finalizar.</li></ul><p className="fine-print">{eligible(bank).filter(q=>!p.seen.includes(q.id)).length} nuevas aptas disponibles en el banco. Este intento, según las cuotas, usará {fullPreview.filter(id=>!p.seen.includes(id)).length} nuevas y {fullPreview.filter(id=>p.seen.includes(id)).length} ya estudiadas. Las identidades se barajan al comenzar.</p><button className="button primary full-width" disabled={maxComplete(bank)<150} onClick={()=>startSim(true)}>Iniciar completo <ArrowRight size={17}/></button>{maxComplete(bank)<150&&<div className="notice">No hay cupo suficiente por dominio para 150. Máximo distribuible: {maxComplete(bank)}. Usa una sesión personalizada más corta.</div>}</section><section className="panel custom-sim"><div className="panel-heading"><PenLine size={20}/><h3>A tu medida</h3></div><p>Elige el alcance y el tiempo. Este modo sí permite pausar.</p><label className="field">Dominios<div className="checkbox-list">{domains.map(d=><label key={d.id}><input type="checkbox" checked={simDomains.includes(d.id)} onChange={()=>setSimDomains(v=>v.includes(d.id)?v.filter(x=>x!==d.id):[...v,d.id])}/><i style={{background:d.color}}/>D{d.id} · {d.short}</label>)}</div></label><label className="field">Dificultad estimada<select value={simDifficulty} onChange={e=>setSimDifficulty(e.target.value)}><option value="">Todas</option>{Object.entries(difficultyNames).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><div className="form-two"><label className="field">Preguntas<input type="number" min={1} max={500} value={simCount} onChange={e=>setSimCount(Number(e.target.value))}/></label><label className="field">Minutos<input type="number" min={1} max={600} value={simMinutes} onChange={e=>setSimMinutes(Number(e.target.value))}/></label></div><div className="availability"><b>{simAvailable.length} aptas</b><span>{simAvailable.filter(q=>!p.seen.includes(q.id)).length} nuevas · {simAvailable.filter(q=>p.seen.includes(q.id)).length} ya estudiadas</span></div><button className="button primary full-width" disabled={!simDomains.length||simCount<1||!Number.isInteger(simCount)||simMinutes<1||simMinutes>600||!Number.isInteger(simMinutes)||simCount>simAvailable.length} onClick={()=>startSim(false)}>Crear mi simulacro <ArrowRight size={17}/></button>{simCount>simAvailable.length&&simAvailable.length>0&&<button className="button secondary full-width" onClick={()=>startSim(false,true)}>Usar las {simAvailable.length} preguntas disponibles</button>}</section></div><section className="panel sim-explanation"><h3>Qué simula esta app y cómo distribuye las preguntas</h3><p>PMI publica 150 preguntas, 180 minutos y 15 ítems no puntuables. Aquí se puntúan las 150 preguntas de práctica con el mismo peso. El examen oficial también contempla un descanso de 10 minutos tras revisar las primeras 75; esta versión usa 180 minutos continuos y no reproduce ese descanso ni los formatos de arrastrar, zonas activas o animaciones.</p><p>Restos mayores (Hamilton): se multiplican 150 × peso, se toman enteros y los cupos restantes se asignan a las fracciones mayores. Empates: número de dominio menor. Resultado: 54 + 26 + 30 + 40 = 150. Es una aproximación de práctica.</p><RefList ids={['exam','eco']} sources={catalog}/></section></section><PdfCollectionsPanel bank={bank} progress={p} onStart={startPdf} onResume={a=>{setP(x=>({...x,activeId:a.id}));go(a.mode==='practica'?'practica':'simulacros')}} onResult={a=>{setResultId(a.id);setResultCollection(attemptCollection(a,bank));go('resultados')}}/></>:
null}
{page==='resultados'&&<><PageTitle eyebrow="LA EVIDENCIA PARA TU SIGUIENTE PASO" title="Mis resultados" text="Cada intento te muestra qué comprendiste y qué conviene volver a explorar."/>{!completed.length?<Empty title="Tu primer resultado empieza con una sesión" text="Completa una práctica o un simulacro para encontrar aquí el análisis." action={<button className="button primary" onClick={()=>go('practica')}>Empezar una práctica <ArrowRight size={16}/></button>}/>:<><div className="results-select"><label>Colección<select aria-label="Colección de resultados" value={resultCollection} onChange={e=>{setResultCollection(e.target.value);setResultId(null);setReviewId(null)}}><option value="all">Todas las colecciones</option>{collections.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}<option value="mixed">Selecciones combinadas</option></select></label><label>Intento<select value={viewedResult?.id??''} onChange={e=>{setResultId(e.target.value);setReviewId(null)}}>{completed.map(a=><option key={a.id} value={a.id}>{new Date(a.startedAt).toLocaleString('es-PE')} · {collectionName(attemptCollection(a,bank))} · {a.mode} · {a.questionIds.length} preguntas</option>)}</select></label><Badge>{completed.length} sesiones finalizadas</Badge></div>{viewedResult&&<><ResultSummary attempt={viewedResult} bank={resultBank}/><div className="results-panels"><section className="panel"><h3>Por dominio</h3>{domains.map(d=>{const qs=resultBank.filter(q=>q.domain===d.id&&viewedResult.questionIds.includes(q.id));const s=score({...viewedResult,questionIds:qs.map(q=>q.id)},bank);return <div className="result-domain" key={d.id}><div><b>D{d.id} · {d.short}</b><span>{s.correct}/{s.graded} · {s.graded?s.percent+'%':'Sin calificación'}</span></div><ProgressBar value={s.percent} color={d.color}/></div>})}</section><section className="panel"><h3>Qué conviene repasar</h3>{(()=>{const wrong=viewedResult.questionIds.map(id=>resultBank.find(q=>q.id===id)!).filter(q=>canGrade(q)&&!isCorrect(q,viewedResult.answers[q.id]));const list=[...new Set(wrong.map(q=>q.topicId))];return list.length?<><p>Basado en errores y omisiones de este intento.</p>{list.slice(0,5).map(id=>{const t=topics.find(t=>t.id===id)!;return <button key={id} className="review-topic" onClick={()=>openTopic(t)}>{t.title}<ArrowRight size={16}/></button>})}{list.length>5&&<small>Y {list.length-5} temas más en la revisión de preguntas.</small>}</>:<p>No hay errores calificables para sugerir un repaso. Consulta también las preguntas pendientes y sin calificación.</p>})()}</section></div><details className="panel breakdown"><summary>Detalle por tarea y tipo</summary><div className="table-scroll"><table><thead><tr><th>Grupo</th><th>Aciertos</th><th>Errores</th><th>Omitidas</th></tr></thead><tbody>{[...tasks.map(t=>({id:t.id,label:t.id+' · '+t.title,match:(q:Question)=>q.taskId===t.id})),...Object.entries(typeNames).map(([id,label])=>({id,label,match:(q:Question)=>q.type===id}))].map(g=>{const ids=viewedResult.questionIds.filter(id=>{const q=resultBank.find(q=>q.id===id)!;return g.match(q)});if(!ids.length)return null;const s=score({...viewedResult,questionIds:ids},bank);return <tr key={g.id}><td>{g.label}</td><td>{s.correct}</td><td>{s.wrong}</td><td>{s.omitted}</td></tr>})}</tbody></table></div></details><div className="section-heading"><h2>Vuelve a cada decisión</h2><select aria-label="Filtrar revisión" value={reviewFilter} onChange={e=>setReviewFilter(e.target.value)}><option value="">Todas</option><option value="error">Errores y omitidas</option><option value="sin-clave">Sin calificación</option><option value="nueva">Nuevas</option><option value="repetida">Ya estudiadas</option></select></div><div className="review-list">{viewedResult.questionIds.map((id,i)=>{const q=resultBank.find(q=>q.id===id)!;const ok=isCorrect(q,viewedResult.answers[id]);const fresh=viewedResult.newIds.includes(id);if((reviewFilter==='sin-clave'&&canGrade(q))||(reviewFilter==='error'&&(!canGrade(q)||ok))||(reviewFilter==='nueva'&&!fresh)||(reviewFilter==='repetida'&&fresh))return null;return <button key={id} onClick={()=>setReviewId(reviewId===id?null:id)} className={reviewId===id?'selected':''}><span className={!canGrade(q)?'status-pending':ok?'status-ok':'status-no'}>{!canGrade(q)?'○':ok?<Check size={17}/>:viewedResult.answers[id]?.selectedIds.length?<X size={17}/>:'—'}</span><span><b>{q.originalNumber??i+1}. {q.stem}</b><small>{collectionName(collectionOf(q))} · {q.taskId} · {!canGrade(q)?'Sin calificación · ':''}{fresh?'Nueva al iniciar':'Ya estudiada'} · {typeNames[q.type]}</small></span><ChevronRight size={17}/></button>})}</div>{reviewId&&<QuestionCard q={resultBank.find(q=>q.id===reviewId)!} attempt={viewedResult} progress={p} sources={catalog} solution locked shuffleOptions={viewedResult.shuffleOptions??p.preferences.shuffle} onAnswer={()=>{}} onBookmark={()=>bookmark(reviewId)} onNote={text=>note(reviewId,text)} onReport={text=>report(reviewId,text)}/>}<p className="fine-print">Puntuación de práctica: un punto si el conjunto elegido coincide exactamente con la solución; cero en errores, selección parcial u omisiones. Las preguntas sin clave o ambiguas quedan fuera del cálculo y no se cuentan como errores. Porcentaje = aciertos / preguntas calificables × 100. No es una predicción ni garantía de aprobación CAPM.</p></>}</> }</>}
{page==='biblioteca'&&<><PageTitle eyebrow="EL CONOCIMIENTO TIENE UN ORIGEN" title="Biblioteca y fuentes" text="Consulta procedencia, conceptos y referencias. Comprueba antes de dar algo por aprendido."/><div className="library-toolbar"><div className="search-input"><Search size={18}/><input id="library-search" aria-label="Buscar por concepto, autor o recurso" placeholder="Busca un concepto, autor o recurso…" value={libSearch} onChange={e=>setLibSearch(e.target.value)}/></div><div className="tabs">{[['todas','Todas'],['externa','Fuentes externas'],['adaptada','Adaptadas'],['ia','Originales de IA']].map(([id,label])=><button key={id} className={libTab===id?'active':''} onClick={()=>setLibTab(id)}>{label}</button>)}</div></div>{(libTab==='todas'||libTab==='externa')&&<><h2 className="subheading">Catálogo de referencias</h2><div className="sources-grid">{catalog.filter(s=>(s.title+' '+s.author+' '+s.section).toLowerCase().includes(libSearch.toLowerCase())).map(s=><article className="source-card" key={s.id}><div className="source-icon"><BookOpen size={21}/></div><div><Badge tone={s.status==='consultada'?'teal':'amber'}>{s.status==='consultada'?'Recurso consultado':'Acceso pendiente'}</Badge><h3>{s.title}</h3><p>{s.author}{s.edition?' · '+s.edition:''}</p><p className="source-section">{s.section}</p>{s.note&&<p className="fine-print">{s.note}</p>}<small>{s.usage}</small><a href={s.localUrl??s.url} target="_blank" rel="noreferrer">Consultar recurso <ExternalLink size={14}/></a><div className="fine-print">Consulta: {s.accessed} · ID: {s.id}</div></div></article>)}</div><div className="library-note"><ShieldCheck size={19}/><p>Recurso externo no significa pregunta copiada. El banco actual contiene {bank.filter(q=>q.origin==='externa').length} externas reproducidas y {bank.filter(q=>q.origin==='adaptada').length} adaptadas. No se consultaron videos ni se inventaron minutos o transcripciones.</p></div></>}<h2 className="subheading">Preguntas por procedencia</h2>{(()=>{const qs=bank.filter(q=>(libTab==='todas'||q.origin===libTab)&&(q.stem+' '+q.concept+' '+q.provenance.author+' '+q.refs.map(r=>[catalog.find(s=>s.id===r.sourceId)?.title,catalog.find(s=>s.id===r.sourceId)?.author].join(' ')).join(' ')).toLowerCase().includes(libSearch.toLowerCase()));return qs.length?<div className="library-questions">{qs.map(q=><article key={q.id}><div className="chip-row"><Badge>{q.id}</Badge><Badge tone={q.review==='contrastado'?'teal':'amber'}>{q.review==='contrastado'?'Fundamento contrastado':'Pendiente'}</Badge><Badge>{originNames[q.origin]}</Badge></div><h3>{q.stem}</h3><p>{q.concept} · {typeNames[q.type]} · {q.humanReviewed?'Revisión humana registrada':'Sin revisión humana'}</p><details><summary>Procedencia y respaldo de la respuesta</summary><p>{q.provenance.author} · {q.provenance.note}</p>{q.provenance.resource&&<p>{q.provenance.resource}</p>}<RefList ids={q.refs.map(r=>r.sourceId)} sources={catalog}/></details><button className="link-button" onClick={()=>startPractice([q])}>Practicar esta pregunta <ArrowRight size={15}/></button></article>)}</div>:<Empty title="Sin preguntas con esta procedencia" text="El catálogo enlaza recursos públicos, pero el banco no copia sus enunciados sin autorización. Cambia de pestaña o búsqueda."/>})()}</>}
{page==='banco'&&<><PageTitle eyebrow="TU CONTENIDO, BAJO TU CONTROL" title="Gestionar banco y progreso" text="Respalda tus sesiones, revisa la cobertura y amplía el banco con un formato validado."/><div className="management-grid"><section className="panel"><div className="panel-heading"><FileJson size={21}/><h3>Banco de preguntas</h3></div><p>{bank.length} preguntas · {catalog.length} fuentes · Formato versión 1</p><div className="button-row"><button className="button secondary" onClick={()=>download('capm-banco-v1.json',{formatVersion:1,questions:bank,sources:catalog})}><Download size={17}/> Exportar banco JSON</button><label className="button primary file-label"><Upload size={17}/> Importar preguntas<input type="file" accept=".json,application/json" onChange={e=>{importFile(e.target.files?.[0],'bank');e.target.value=''}}/></label></div><p className="fine-print">Se validan todas las preguntas y referencias antes de guardar. Se añaden IDs nuevos; un ID existente con contenido distinto se rechaza sin sobrescribir.</p></section><section className="panel"><div className="panel-heading"><ShieldCheck size={21}/><h3>Tu progreso personal</h3></div><p>{p.history.length} respuestas · {p.attempts.length} sesiones · {p.reports.length} reportes</p><div className="button-row"><button className="button secondary" onClick={()=>download('capm-progreso-v1.json',p)}><Download size={17}/> Exportar progreso</button><label className="button primary file-label"><Upload size={17}/> Importar progreso<input type="file" accept=".json,application/json" onChange={e=>{importFile(e.target.files?.[0],'progress');e.target.value=''}}/></label></div><p className="fine-print">Un progreso válido reemplaza el activo después de crear un respaldo local del anterior. Primero importa el banco si contiene IDs de preguntas que todavía no tienes.</p></section></div>{importError&&<div className="import-error" role="alert"><b>No se importó el archivo. Tus datos siguen intactos.</b><pre>{importError}</pre></div>}{importStatus&&<div className="notice" role="status">{importStatus}</div>}<section className="panel preferences"><h3>Preferencias</h3><label><input type="checkbox" checked={p.preferences.shuffle} onChange={e=>setP(x=>({...x,preferences:{...x.preferences,shuffle:e.target.checked}}))}/> Barajar alternativas conservando sus identificadores y corrección</label><p className="fine-print">No se cambia el orden dentro de una sesión al recargar: se utiliza su semilla persistida.</p></section><Coverage bank={originalBank}/><section className="panel reference-version"><h3>Versión del temario y alcance editorial</h3><p>Referencia de esta app: estructura proporcionada por Leython, contrastada el 22 de octubre de 2026 con el ECO público cuya portada indica “2023 Exam Update”. Coinciden 4 dominios, 19 tareas y pesos 36 / 17 / 20 / 27. No se identificó cambio material en esa estructura.</p><p>Grupos de procesos, PMO y liderazgo servicial son desarrollos complementarios vinculados a las tareas. Los ocho dominios de desempeño del PMBOK 7 no sustituyen los cuatro dominios del examen. Las colecciones personales se identifican por separado. Un documento pendiente de lectura no añade preguntas ni estadísticas al banco.</p><p>El código ético enlazado por PMI fue actualizado con vigencia desde el 17 de noviembre de 2025. Aquí se contrastaron los cuatro valores de la página pública; no se atribuyen artículos del código completo.</p><p>Meta inicial: 300 preguntas distintas. El banco original contiene {originalBank.length}; faltan {Math.max(0,300-originalBank.length)} para esa meta. Todos los subtemas solicitados tienen contenido introductorio, a veces agrupados; no todos tienen todavía un par independiente de preguntas conceptual/situacional. Falta ampliar profundidad y variedad, especialmente cálculo de redes, prácticas de SAFe, roles del proceso y preguntas avanzadas.</p><p>“Fundamento contrastado” indica comparación de la explicación con una referencia consultada por IA. No implica revisión humana, calibración estadística ni aprobación de PMI. Las preguntas pendientes quedan excluidas de simulacros.</p><RefList ids={['eco','samples','ethics']} sources={catalog}/></section></>}
<footer className="footer"><span>CAPM <b>—</b> Centro de estudio de Leython</span><span>Aprender. Comprender. Avanzar.</span></footer></main></div></div>
}
function PageTitle({eyebrow,title,text}:{eyebrow:string;title:string;text:string}){return <div className="page-title"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{text}</p></div>}
function formatTime(ms:number){const s=Math.max(0,Math.ceil(ms/1000));return [Math.floor(s/3600),Math.floor(s/60)%60,s%60].map(n=>String(n).padStart(2,'0')).join(':')}
function Coverage({bank}:{bank:Question[]}){return <><div className="section-heading"><div><span className="eyebrow">COBERTURA REAL DEL BANCO</span><h2>Lo disponible y lo pendiente</h2></div><button className="button secondary small" onClick={()=>download('capm-cobertura.json',{generatedAt:'2026-10-22',target:300,total:bank.length,domains:domains.map(d=>({...d,total:bank.filter(q=>q.domain===d.id).length,eligible:eligible(bank).filter(q=>q.domain===d.id).length})),topics:topics.map(t=>({...t,total:bank.filter(q=>q.topicId===t.id).length,pending:bank.filter(q=>q.topicId===t.id&&q.review==='pendiente').length,conceptual:bank.filter(q=>q.topicId===t.id&&q.type==='conceptual').length,situational:bank.filter(q=>q.topicId===t.id&&q.type==='situacional').length}))})}><Download size={15}/> Informe JSON</button></div><div className="coverage-counts">{['ia','externa','adaptada'].map(o=><div className="panel" key={o}><b>{bank.filter(q=>q.origin===o).length}</b><span>{originNames[o]}</span></div>)}<div className="panel"><b>{bank.filter(q=>q.review==='pendiente').length}</b><span>Pendientes de contraste</span></div></div><div className="panel table-scroll"><table><thead><tr><th>Dominio</th><th>Peso</th><th>Preguntas</th><th>Aptas</th><th>Revisión humana</th></tr></thead><tbody>{domains.map(d=><tr key={d.id}><td><i className="table-dot" style={{background:d.color}}/>D{d.id} · {d.short}</td><td>{d.weight}%</td><td>{bank.filter(q=>q.domain===d.id).length}</td><td>{eligible(bank).filter(q=>q.domain===d.id).length}</td><td>{bank.filter(q=>q.domain===d.id&&q.humanReviewed).length}</td></tr>)}</tbody></table></div><details className="panel coverage-details"><summary>Ver las 19 tareas y los {topics.length} subtemas del banco</summary>{tasks.map(t=><div className="coverage-task" key={t.id}><h4>{t.id} · {t.title} <small>{bank.filter(q=>q.taskId===t.id).length} preguntas</small></h4>{topics.filter(topic=>topic.taskId===t.id).map(topic=>{const qs=bank.filter(q=>q.topicId===topic.id);return <div key={topic.id}><span>{topic.title}</span><span>{qs.length} preguntas · {qs.filter(q=>q.review==='contrastado').length} aptas · {qs.some(q=>q.type==='conceptual')?'C ✓':'C —'} / {qs.some(q=>q.type==='situacional')?'S ✓':'S —'}</span></div>})}</div>)}</details></>}
